const cards=[
['substantial','adjective','大幅な・かなりの','large in amount, size, or importance','The policy led to a substantial（大幅な） reduction in traffic.'],
['mitigate','verb','和らげる・軽減する','to make a harmful effect less severe','Trees can mitigate（和らげる） the effects of extreme heat.'],
['prevalent','adjective','広く見られる・一般的な','common or existing in many places','Remote work is increasingly prevalent（広く見られる） in large cities.'],
['allocate','verb','割り当てる','to give money, time, or resources for a particular purpose','The council allocated（割り当てた） funds to public transport.'],
['inherent','adjective','本質的に備わった','existing as a natural and permanent part of something','There is an inherent（本質的な） risk in any major change.'],
['consecutive','adjective','連続した','following one after another without interruption','The region experienced three consecutive（連続した） years of drought.'],
['compelling','adjective','説得力のある・強い','very convincing or able to attract strong interest','The researchers presented compelling（説得力のある） evidence.'],
['constraint','noun','制約・制限','something that limits what can be done','Cost is a major constraint（制約） for many local governments.'],
['disparity','noun','大きな差・格差','a noticeable difference, especially an unfair one','The study revealed a disparity（格差） in access to healthcare.'],
['deteriorate','verb','悪化する','to become worse','Air quality can deteriorate（悪化する） rapidly during heatwaves.'],
['feasible','adjective','実行可能な','possible and practical to do','The plan is feasible（実行可能な）, but it will require cooperation.'],
['negligible','adjective','ごくわずかな・無視できる','so small that it is not worth considering','The change had a negligible（ごくわずかな） effect on total costs.']
];
const sentences=[
{s:'Although the government <mark>allocated</mark> additional funding to rail services, the improvement was <mark>negligible</mark> because demand had risen even faster.',q:'政府の追加資金について、最も正しい説明はどれですか？',a:['鉄道サービスは大幅に改善した。','需要がより速く増えたため、改善はごくわずかだった。','政府は鉄道への資金提供をやめた。','需要は急激に減少した。'],correct:1,why:'although（〜にもかかわらず）の後を見ると、資金は増えましたが、改善は negligible（ごくわずか）でした。'},
{s:'The researchers argue that the health gap is not an <mark>inherent</mark> feature of city life but a problem that can be <mark>mitigated</mark> through targeted policy.',q:'筆者の主張は何ですか？',a:['都市の健康格差は変えられない。','健康格差は自然に消える。','適切な政策により健康格差は軽減できる。','都市生活には健康格差が存在しない。'],correct:2,why:'not inherent = 本質的に避けられないものではない。mitigated = 政策で和らげられる、です。'},
{s:'While electric vehicles are becoming more <mark>prevalent</mark>, their environmental benefit depends on whether the electricity used to charge them comes from low-carbon sources.',q:'この文の main point は何ですか？',a:['電気自動車は常に環境に良い。','電気自動車の環境上の利点は、電力源によって左右される。','電気自動車はあまり一般的ではない。','低炭素電力は不要である。'],correct:1,why:'depends on whether… = 〜かどうかによって決まる。普及していることと、必ず環境に良いことは別です。'},
{s:'Because of financial <mark>constraints</mark>, the proposal was considered technically <mark>feasible</mark> but politically unlikely to be adopted.',q:'提案について正しいのはどれですか？',a:['技術的にも政治的にも不可能だった。','お金の問題はなかった。','実行は技術的に可能だが、政治的に採用されにくかった。','すでに採用された。'],correct:2,why:'technically feasible（技術的には可能）と politically unlikely（政治的には起こりにくい）の対比です。'},
{s:'The report found a <mark>substantial</mark> disparity between neighbourhoods, with residents in poorer areas experiencing consistently higher exposure to pollution.',q:'報告書が示した内容は何ですか？',a:['貧しい地域ほど汚染への曝露が継続して高い。','地域間に差はなかった。','裕福な地域ほど常に汚染が高い。','汚染は完全に解決された。'],correct:0,why:'substantial disparity = 大きな格差。poorer areas と higher exposure の関係を読み取ります。'}
];
const passage=`<h3>Why some cities cool more fairly than others</h3><p class="source">ORIGINAL ACADEMIC READING PRACTICE · URBAN POLICY</p><p>As heatwaves become more <span class="annot">prevalent（広く見られる）</span>, city governments have begun to treat extreme heat as a public-health issue rather than a seasonal inconvenience. Yet the effects of high temperatures are not evenly distributed. In many urban areas, a <span class="annot">substantial（大幅な）</span> difference exists between leafy, well-resourced neighbourhoods and districts with little shade or poor housing.</p><p>Planting trees is often presented as a simple solution. Trees can <span class="annot">mitigate（和らげる）</span> heat by shading streets and releasing water vapour. However, the benefit is not automatic. Young trees require maintenance, while land in densely built areas is limited. These practical <span class="annot">constraints（制約）</span> mean that an impressive number of new trees on paper may produce only a <span class="annot">negligible（ごくわずかな）</span> change for residents who need relief most.</p><p>Some cities are therefore using detailed maps that combine temperature readings with information about age, income and access to cooling. The aim is to identify not merely the hottest locations but the people most exposed to danger. Such data can reveal a <span class="annot">disparity（格差）</span> that city-wide averages conceal. A policy may be technically <span class="annot">feasible（実行可能な）</span>, for example, but still fail if it ignores where vulnerable residents actually live.</p><p>The most <span class="annot">compelling（説得力のある）</span> lesson is that cooling measures should be judged by their effect on people, not by the number of projects announced. A city that simply copies another city’s plan may overlook its own climate, housing and social conditions. Effective action requires local evidence and the willingness to adjust a policy when it does not work.</p>`;
const readQs=[
{q:'What is the main point of Paragraph 2?',opts:['Tree planting always solves urban heat.','Trees can help, but practical limits may reduce their real impact.','Young trees need no care.','Heat is not a health issue.'],c:1,why:'段落2は trees のメリットを認めながら、制約により効果が小さくなる可能性を説明しています。'},
{q:'The word “conceal” in Paragraph 3 is closest in meaning to:',opts:['hide','measure','reduce','predict'],c:0,why:'conceal = hide（隠す）。ここでは都市全体の平均が、地域間の格差を見えにくくするという意味です。'},
{q:'TRUE / FALSE / NOT GIVEN: The passage says that every technically feasible policy will improve the lives of vulnerable residents.',opts:['TRUE','FALSE','NOT GIVEN'],c:1,why:'Paragraph 3 says a technically feasible policy can still fail if it ignores where vulnerable residents live. Therefore, the statement is FALSE.'},
{q:'Which statement best reflects the writer’s conclusion?',opts:['Cities should use exactly the same cooling policy.','Project numbers are the best measure of success.','Local evidence should guide and improve policies.','Only wealthy neighbourhoods benefit from trees.'],c:2,why:'最後の段落は local evidence と policy adjustment の重要性を結論として述べています。'}
];
let mode='flash',i=0,shown=false,review=[],correctStreak=0,mem=0,round=null;
const game=document.querySelector('#game'),pick=a=>[...a].sort(()=>Math.random()-.5);
function save(){localStorage.setItem('ieltsReadingLabBand8',JSON.stringify({review,mem,correctStreak}))}function load(){try{let x=JSON.parse(localStorage.getItem('ieltsReadingLabBand8'));if(x){review=x.review||[];mem=x.mem||0;correctStreak=x.correctStreak||0}}catch(e){}}function stats(){document.querySelector('#remembered').textContent=mem;document.querySelector('#streak').textContent=correctStreak;document.querySelector('#reviewCount').textContent=review.length}
function controls(next){return `<div class="controls"><button class="btn" id="prev">← Previous</button><div><button class="btn" id="mix">Mix cards</button> <button class="btn primary" id="next">${next}</button></div></div>`}
function flash(){let card=cards[i];game.innerHTML=`<h2 class="mode-title">Flashcards</h2><p class="subtitle">Say the meaning first. Then flip — and meet the word again in an IELTS sentence.</p><div class="counter"><span>CARD ${i+1} / ${cards.length}</span><span>Academic Core · Band 7–8</span></div><div class="progress"><i style="width:${(i+1)/cards.length*100}%"></i></div><article class="flashcard ${shown?'revealed':''}" id="card"><div class="front"><div class="pos">${card[1].toUpperCase()}</div><div class="word">${card[0]}</div><p class="hint">Tap or click to reveal the answer ↻</p></div><div class="answer-card"><div class="jp">${card[2]}</div><div class="definition">${card[3]}</div><div class="example">${card[4]}</div><p class="hint">The Japanese bracket helps you read without stopping.</p></div></article>${controls('✓ I remembered')}`;document.querySelector('#card').onclick=()=>{shown=!shown;flash()};document.querySelector('#prev').onclick=()=>{i=(i-1+cards.length)%cards.length;shown=false;flash()};document.querySelector('#mix').onclick=()=>{cards.sort(()=>Math.random()-.5);i=0;shown=false;flash()};document.querySelector('#next').onclick=()=>{if(!shown){shown=true;flash();return}mem++;correctStreak++;i=(i+1)%cards.length;shown=false;save();stats();flash()}}
function choiceGame(kind){let dataset=kind==='meaning'?cards.map(c=>({prompt:`What is the closest Japanese meaning of “${c[0]}”?`,ans:c[2],why:`${c[0]} = ${c[2]}. Example: ${c[4]}`})):sentences.map(x=>({prompt:x.q,ans:x.a[x.correct],why:x.why,s:x.s}));if(!round||round.kind!==kind)round={kind,items:pick(dataset),n:0};let x=round.items[round.n],distr=pick(dataset.filter(y=>y.ans!==x.ans).map(y=>y.ans)).slice(0,3),opts=pick([x.ans,...distr]);game.innerHTML=`<h2 class="mode-title">${kind==='meaning'?'Meaning Match':'Sentence Detective'}</h2><p class="subtitle">${kind==='meaning'?'Choose the closest meaning. The answer positions mix every round.':'Read the whole idea first. Japanese question, English sentence.'}</p><div class="counter"><span>QUESTION ${round.n+1} / ${round.items.length}</span><span>${kind==='meaning'?'Vocabulary in context':'Find the structure'}</span></div><div class="progress"><i style="width:${(round.n+1)/round.items.length*100}%"></i></div>${x.s?`<div class="sentence-box">${x.s}</div>`:''}<p class="task">${x.prompt}</p><div class="choices">${opts.map((o,n)=>`<button class="choice" data-n="${n}"><b>${'ABCD'[n]}</b>　${o}</button>`).join('')}</div><div id="fb"></div>`;document.querySelectorAll('.choice').forEach((b,n)=>b.onclick=()=>grade(b,opts[n]===x.ans,x,()=>{round.n=(round.n+1)%round.items.length;choiceGame(kind)}))}
function grade(btn,ok,x,next){document.querySelectorAll('.choice').forEach(b=>b.disabled=true);btn.classList.add(ok?'correct':'wrong');if(!ok){[...document.querySelectorAll('.choice')].find(b=>b.textContent.includes(x.ans)).classList.add('correct');review.push(x.prompt)}correctStreak=ok?correctStreak+1:0;save();stats();document.querySelector('#fb').innerHTML=`<div class="feedback"><strong>${ok?'Correct — good evidence.':'Check the clue.'}</strong>${x.why}<br><button class="btn primary" id="continue">Next question →</button></div>`;document.querySelector('#continue').onclick=next}
function reading(){if(!round||round.kind!=='reading')round={kind:'reading',items:pick(readQs),n:0};let x=round.items[round.n],opts=pick(x.opts.map((t,n)=>({t,ok:n===x.c})));game.innerHTML=`<h2 class="mode-title">Reading Quest</h2><p class="subtitle">First, use the Japanese brackets to keep moving. Then answer from evidence — not from guessing.</p><div class="counter"><span>QUESTION ${round.n+1} / ${round.items.length}</span><span>Band 7–8 mini passage</span></div><div class="progress"><i style="width:${(round.n+1)/round.items.length*100}%"></i></div><div class="reading-layout"><article class="passage">${passage}</article><section><p class="reading-q">${x.q}</p><div class="choices">${opts.map((o,n)=>`<button class="choice" data-n="${n}"><b>${'ABCD'[n]}</b>　${o.t}</button>`).join('')}</div><div id="fb"></div></section></div>`;document.querySelectorAll('.choice').forEach((b,n)=>b.onclick=()=>grade(b,opts[n].ok,x,()=>{round.n=(round.n+1)%round.items.length;reading()}))}
function render(){document.querySelectorAll('.mode').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(mode==='flash')flash();if(mode==='meaning')choiceGame('meaning');if(mode==='sentence')choiceGame('sentence');if(mode==='reading')reading();stats()}
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;round=null;render()});document.querySelector('#reviewBtn').onclick=()=>{alert(review.length?'Review pile:\n• '+review.slice(-8).join('\n• '):'No missed items yet — nice work!')};load();render();
